let courseCache = []
let examCache = []
let taskCache = []
let semesterWeek1StartCache = null // 学期第一周周一日期字符串 YYYY-MM-DD
let useMockDataCache = true // 默认启用Mock数据
let storageReady = false
let initPromise = null

/**
 * 同步Mock数据设置状态
 * 从Storage读取最新状态并更新缓存
 * @returns {Promise<boolean>}
 */
export function syncMockDataSetting() {
  return new Promise((resolve) => {
    storage.get({
      key: STORAGE_KEYS.DEBUG_USE_MOCK_DATA,
      success: function (data) {
        useMockDataCache = data !== 'false' // 默认为true
        console.log('[DEBUG] syncMockDataSetting:', useMockDataCache)
        resolve(useMockDataCache)
      },
      fail: function () {
        useMockDataCache = true
        console.log('[DEBUG] syncMockDataSetting (fail, default true)')
        resolve(true)
      }
    })
  })
}

/**
 * 从 Storage 重新读取考试数据
 * @returns {Promise<Array>}
 */
export function refreshExamsFromStorage() {
  return new Promise((resolve, reject) => {
    // 先同步Mock数据设置
    syncMockDataSetting().then(() => {
      storage.get({
        key: STORAGE_KEYS.EXAMS,
        success: function (data) {
          try {
            // 没有持久化数据时使用空数组（Mock数据在getExams()中动态合并）
            const parsed = data ? JSON.parse(data) : []
            // 生成新的数组和对象，避免引用旧对象
            examCache = parsed.map(exam => ({ ...exam }))
            resolve(examCache)
          } catch (e) {
            console.error('Failed to parse exams on refresh:', e)
            // 读取失败时保留当前缓存
            resolve(examCache)
          }
        },
        fail: function (data, code) {
          console.error('Failed to refresh exams from storage:', code)
          // 读取失败时保留当前缓存
          resolve(examCache)
        }
      })
    })
  })
}

