        if (data === 'true') {
          useMockDataCache = true
        } else if (data === 'false') {
          useMockDataCache = false
        }
        // 首次没有设置时保持当前缓存（默认true）
        console.log('[DEBUG] syncMockDataSetting:', useMockDataCache, '(raw:', data, ')')
        resolve(useMockDataCache)
      },
      fail: function () {
