/**
 * 时间工具模块
 * 提供日期格式化、倒计时计算等功能
 */

/**
 * 获取当前时间（支持调试覆盖）
 * @param {Date} debugNow 调试用时间
 * @returns {Date}
 */
export function getNow(debugNow) {
  return debugNow || new Date()
}

/**
 * 格式化时间为 HH:MM
 * @param {Date} date
 * @returns {string}
 */
export function formatTime(date) {
  const hours = String(date.getHours()).padStart(2, '0')
  const minutes = String(date.getMinutes()).padStart(2, '0')
  return `${hours}:${minutes}`
}

/**
 * 格式化完整日期：8月18日 · 周二
 * @param {Date} date
 * @returns {string}
 */
export function formatFullDate(date) {
  const month = date.getMonth() + 1
  const day = date.getDate()
  const days = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']
  return `${month}月${day}日 · ${days[date.getDay()]}`
}

/**
 * 解析时间字符串为当天的 Date 对象
 * @param {string} timeStr 格式：HH:MM
 * @param {Date} baseDate 基准日期
 * @returns {Date}
 */
export function parseTimeToDate(timeStr, baseDate) {
  const [hours, minutes] = timeStr.split(':').map(Number)
  const date = new Date(baseDate)
  date.setHours(hours, minutes, 0, 0)
  return date
}

/**
 * 解析日期时间字符串
 * @param {string} dateTimeStr 格式：YYYY-MM-DDTHH:MM:SS
 * @returns {Date|null} 解析失败返回 null
 */
export function parseDateTime(dateTimeStr) {
  if (!dateTimeStr) {
    return null
  }
  const date = new Date(dateTimeStr)
  if (isNaN(date.getTime())) {
    return null
  }
  return date
}

/**
 * 计算两个时间之间的分钟差
 * @param {Date} start
 * @param {Date} end
 * @returns {number}
 */
export function diffMinutes(start, end) {
  return Math.floor((end - start) / (1000 * 60))
}

/**
 * 格式化倒计时（考试用）
 * @param {Date} targetDate
 * @param {Date} now
 * @returns {object} { value, unit }
 */
export function formatCountdown(targetDate, now) {
  const diffMs = targetDate - now
  if (diffMs <= 0) return { value: 0, unit: '已结束', isFinished: true }

  const diffHours = Math.floor(diffMs / (1000 * 60 * 60))
  const diffDays = Math.floor(diffHours / 24)

  if (diffDays > 0) {
    return { value: diffDays, unit: '天', isFinished: false }
  }
  if (diffHours > 0) {
    return { value: diffHours, unit: '小时', isFinished: false }
  }

  const diffMins = Math.floor(diffMs / (1000 * 60))
  return { value: diffMins, unit: '分钟', isFinished: false }
}

/**
 * 格式化考试倒计时（精确到秒）
 * @param {Date} targetDate
 * @param {Date} now
 * @returns {string}
 */
export function formatExamCountdown(targetDate, now) {
  const diffMs = targetDate - now
  if (diffMs <= 0) return '已结束'

  const totalSeconds = Math.floor(diffMs / 1000)
  const hours = Math.floor(totalSeconds / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60

  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
}

/**
 * 获取星期数字（1-7，1是周一）
 * @param {Date} date
 * @returns {number}
 */
export function getWeekdayNumber(date) {
  const day = date.getDay()
  return day === 0 ? 7 : day
}

/**
 * 判断是否是今天
 * @param {Date} date
 * @param {Date} now
 * @returns {boolean}
 */
export function isToday(date, now) {
  if (!date || !now) {
    return false
  }
  return date.getFullYear() === now.getFullYear() &&
    date.getMonth() === now.getMonth() &&
    date.getDate() === now.getDate()
}

/**
 * 课程逻辑模块
 * 提供课程筛选、当前课程判断、下一课程查找等功能
 */

import { getCourses, getSemesterWeek1Start } from './storage'
import { getNow, parseTimeToDate, diffMinutes, getWeekdayNumber } from './time'

/**
 * 获取学期第一周的周一日期
 * @returns {Date|null}
 */
function getWeek1Monday() {
  const week1Start = getSemesterWeek1Start()
  if (!week1Start) {
    return null
  }
  return new Date(week1Start + 'T00:00:00')
}

/**
 * 根据日期计算该日期所在周的周一
 * @param {Date} date
 * @returns {Date}
 */
function getMondayOfWeek(date) {
  const d = new Date(date)
  const day = d.getDay()
  const diff = d.getDate() - day + (day === 0 ? -6 : 1)
  d.setDate(diff)
  d.setHours(0, 0, 0, 0)
  return d
}

/**
 * 计算当前教学周
 * @param {Date} now 当前时间
 * @returns {number} 教学周数，未设置学期第一周时返回1，在学期开始前返回0
 */
export function calculateCurrentWeek(now) {
  const week1Monday = getWeek1Monday()

  // 如果未设置学期第一周，默认返回第1周
  if (!week1Monday) {
    return 1
  }

  // 计算当前日期所在周的周一
  const currentMonday = getMondayOfWeek(now)

  // 计算周数差
  const diffTime = currentMonday.getTime() - week1Monday.getTime()
  const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24))
  const weekNumber = Math.floor(diffDays / 7) + 1

  // 如果在第一周之前，返回0表示学期开始前
  if (weekNumber < 1) {
    return 0
  }

  return weekNumber
}

/**
 * 获取今天的课程列表
 * @param {Date} now 当前时间
 * @param {number} currentWeek 当前教学周（不传则自动计算）
 * @returns {Array}
 */
export function getTodayCourses(now, currentWeek) {
  const week = currentWeek !== undefined ? currentWeek : calculateCurrentWeek(now)
  const weekday = getWeekdayNumber(now)
  return getCourses()
    .filter(c => c.weekday === weekday && Array.isArray(c.weeks) && c.weeks.includes(week))
    .sort((a, b) => a.startTime.localeCompare(b.startTime))
}

/**
 * 获取指定星期的课程（按教学周过滤）
 * @param {number} weekday 星期几（1-7）
 * @param {number} currentWeek 当前教学周
 * @returns {Array}
 */
export function getCoursesByWeekday(weekday, currentWeek = 1) {
  return getCourses()
    .filter(c => c.weekday === weekday && Array.isArray(c.weeks) && c.weeks.includes(currentWeek))
    .sort((a, b) => a.startTime.localeCompare(b.startTime))
}

/**
 * 获取指定星期的所有课程（不按教学周过滤，用于全部模式）
 * @param {number} weekday 星期几（1-7）
 * @returns {Array}
 */
export function getAllCoursesByWeekday(weekday) {
  return getCourses()
    .filter(c => c.weekday === weekday)
    .sort((a, b) => a.startTime.localeCompare(b.startTime))
}

/**
 * 格式化课程周次显示
 * @param {Array} weeks 周次数组
 * @returns {string}
 */
export function formatCourseWeeks(weeks) {
  if (!weeks || weeks.length === 0) return ''

  const totalWeeks = 16
  const allWeeks = Array.from({ length: totalWeeks }, (_, i) => i + 1)

  // 判断是否为全周课程（1-16周）
  if (weeks.length === totalWeeks && allWeeks.every(w => weeks.includes(w))) {
    return '1-16周'
  }

  // 判断是否为单周（奇数周）
  const oddWeeks = allWeeks.filter(w => w % 2 === 1)
  if (weeks.length === oddWeeks.length && oddWeeks.every(w => weeks.includes(w))) {
    return '单周'
  }

  // 判断是否为双周（偶数周）
  const evenWeeks = allWeeks.filter(w => w % 2 === 0)
  if (weeks.length === evenWeeks.length && evenWeeks.every(w => weeks.includes(w))) {
    return '双周'
  }

  // 不规则周次，显示具体周次
  return weeks.join(',') + '周'
}

/**
 * 获取当前正在进行的课程
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {object|null}
 */
export function getCurrentCourse(now, currentWeek) {
  const week = currentWeek !== undefined ? currentWeek : calculateCurrentWeek(now)
  const todayCourses = getTodayCourses(now, week)
  for (const course of todayCourses) {
    const startTime = parseTimeToDate(course.startTime, now)
    const endTime = parseTimeToDate(course.endTime, now)
    if (now >= startTime && now < endTime) {
      return course
    }
  }
  return null
}

/**
 * 获取下一节课（今天内）
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {object|null}
 */
export function getNextCourse(now, currentWeek) {
  const week = currentWeek !== undefined ? currentWeek : calculateCurrentWeek(now)
  const todayCourses = getTodayCourses(now, week)
  for (const course of todayCourses) {
    const startTime = parseTimeToDate(course.startTime, now)
    if (startTime > now) {
      return course
    }
  }
  return null
}

/**
 * 跨天查找下一节课
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {object|null} { course, daysLater, date }
 */
export function getNextCourseAcrossDays(now, currentWeek) {
  const week = currentWeek !== undefined ? currentWeek : calculateCurrentWeek(now)

  // 先检查今天剩余课程
  const nextToday = getNextCourse(now, week)
  if (nextToday) {
    return { course: nextToday, daysLater: 0, date: now }
  }

  // 检查未来7天
  for (let i = 1; i <= 7; i++) {
    const futureDate = new Date(now)
    futureDate.setDate(futureDate.getDate() + i)
    const weekday = getWeekdayNumber(futureDate)
    // 为每个未来日期计算它自己的教学周
    const futureWeek = calculateCurrentWeek(futureDate)
    // 跳过学期未开始的情况
    if (futureWeek < 1) {
      continue
    }
    const courses = getCoursesByWeekday(weekday, futureWeek)
    if (courses.length > 0) {
      return { course: courses[0], daysLater: i, date: futureDate }
    }
  }

  return null
}

/**
 * 获取课程进度（0-1）
 * @param {object} course
 * @param {Date} now
 * @returns {number}
 */
export function getCourseProgress(course, now) {
  const startTime = parseTimeToDate(course.startTime, now)
  const endTime = parseTimeToDate(course.endTime, now)
  const total = endTime - startTime
  const elapsed = now - startTime
  const progress = elapsed / total
  return Math.max(0, Math.min(1, progress))
}

/**
 * 获取课程剩余时间（分钟）
 * @param {object} course
 * @param {Date} now
 * @returns {number}
 */
export function getCourseRemainingTime(course, now) {
  const endTime = parseTimeToDate(course.endTime, now)
  return Math.max(0, diffMinutes(now, endTime))
}

/**
 * 获取课程状态
 * @param {object} course
 * @param {Date} now
 * @returns {string} 'finished' | 'ongoing' | 'upcoming'
 */
export function getCourseStatus(course, now) {
  const startTime = parseTimeToDate(course.startTime, now)
  const endTime = parseTimeToDate(course.endTime, now)
  if (now >= endTime) return 'finished'
  if (now >= startTime) return 'ongoing'
  return 'upcoming'
}

/**
 * 获取距离开始的分钟数
 * @param {object} course
 * @param {Date} now
 * @returns {number}
 */
export function getMinutesUntilStart(course, now) {
  const startTime = parseTimeToDate(course.startTime, now)
  return Math.max(0, diffMinutes(now, startTime))
}

/**
 * 判断今日课程是否全部结束
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {boolean}
 */
export function isTodayCoursesFinished(now, currentWeek) {
  const week = currentWeek !== undefined ? currentWeek : calculateCurrentWeek(now)
  const todayCourses = getTodayCourses(now, week)
  if (todayCourses.length === 0) return true
  return todayCourses.every(c => getCourseStatus(c, now) === 'finished')
}

/**
 * 考试逻辑模块
 * 提供考试筛选、倒计时计算等功能
 */

import { getExams } from './storage'
import { formatCountdown, parseDateTime } from './time'

/**
 * 获取最近的考试（优先选择进行中的考试）
 * 选择优先级：
 * 1. 正在进行中的考试（结束时间更早的优先）
 * 2. 即将开始的考试（开始时间更早的优先）
 * @param {Date} now
 * @returns {object|null}
 */
export function getNearestExam(now) {
  const exams = getExams()
  const validExams = exams
    .filter(e => {
      // 考试结束时间 > 当前时间 才算有效
      const examEnd = parseDateTime(`${e.date}T${e.endTime}:00`)
      return examEnd > now
    })

  // 分类：进行中 和 即将开始
  const ongoingExams = []
  const upcomingExams = []

  validExams.forEach(e => {
    const status = getExamStatus(e, now)
    if (status === 'ongoing') {
      ongoingExams.push(e)
    } else {
      upcomingExams.push(e)
    }
  })

  // 优先选择进行中的考试
  if (ongoingExams.length > 0) {
    // 多个进行中考试时，选择结束时间更早的
    ongoingExams.sort((a, b) => {
      const endA = parseDateTime(`${a.date}T${a.endTime}:00`)
      const endB = parseDateTime(`${b.date}T${b.endTime}:00`)
      return endA - endB
    })
    return ongoingExams[0]
  }

  // 否则选择即将开始的考试
  upcomingExams.sort((a, b) => {
    const startA = parseDateTime(`${a.date}T${a.startTime}:00`)
    const startB = parseDateTime(`${b.date}T${b.startTime}:00`)
    return startA - startB
  })

  return upcomingExams.length > 0 ? upcomingExams[0] : null
}

/**
 * 获取所有即将到来的考试（包括进行中的考试）
 * @param {Date} now
 * @returns {Array}
 */
export function getUpcomingExams(now) {
  const exams = getExams()
  return exams
    .filter(e => {
      // 考试结束时间 > 当前时间 才算有效
      const examEnd = parseDateTime(`${e.date}T${e.endTime}:00`)
      return examEnd > now
    })
    .sort((a, b) => {
      const dateA = parseDateTime(`${a.date}T${a.startTime}:00`)
      const dateB = parseDateTime(`${b.date}T${b.startTime}:00`)
      return dateA - dateB
    })
}

/**
 * 获取考试倒计时（根据状态返回不同信息）
 * @param {object} exam
 * @param {Date} now
 * @returns {object} { value, unit, status, isOngoing }
 */
export function getExamCountdown(exam, now) {
  const status = getExamStatus(exam, now)
  const examDate = parseDateTime(`${exam.date}T${exam.startTime}:00`)
  const examEnd = parseDateTime(`${exam.date}T${exam.endTime}:00`)

  if (status === 'ongoing') {
    // 考试进行中：计算剩余时间
    const remaining = examEnd - now
    const totalMinutes = Math.floor(remaining / (1000 * 60))
    const hours = Math.floor(totalMinutes / 60)
    const minutes = totalMinutes % 60

    if (hours > 0) {
      return { value: hours, unit: '小时', status: 'ongoing', isOngoing: true, remainingMinutes: minutes }
    }
    return { value: minutes, unit: '分钟', status: 'ongoing', isOngoing: true, remainingMinutes: 0 }
  }

  // 考试未开始：计算距离开始的时间
  const result = formatCountdown(examDate, now)
  return { ...result, status: status, isOngoing: false }
}

/**
 * 获取考试日期格式化
 * @param {object} exam
 * @returns {string} 如：8月21日 · 09:00
 */
export function formatExamDate(exam) {
  const date = parseDateTime(`${exam.date}T00:00:00`)
  const month = date.getMonth() + 1
  const day = date.getDate()
  return `${month}月${day}日 · ${exam.startTime}`
}

/**
 * 获取考试状态
 * @param {object} exam
 * @param {Date} now
 * @returns {string} 'upcoming' | 'today' | 'ongoing' | 'finished'
 */
export function getExamStatus(exam, now) {
  const examDate = parseDateTime(`${exam.date}T${exam.startTime}:00`)
  const examEnd = parseDateTime(`${exam.date}T${exam.endTime}:00`)

  if (now >= examEnd) return 'finished'
  if (now >= examDate) return 'ongoing'

  // 判断是否是今天
  const examDay = new Date(exam.date)
  if (examDay.toDateString() === now.toDateString()) return 'today'

  return 'upcoming'
}

/**
 * 获取考试数量摘要
 * @param {Date} now
 * @returns {object} { count, nearestCourse, daysUntil }
 */
export function getExamSummary(now) {
  const nearest = getNearestExam(now)
  if (!nearest) {
    return { count: 0, nearestCourse: null, daysUntil: null }
  }

  const countdown = getExamCountdown(nearest, now)
  return {
    count: getUpcomingExams(now).length,
    nearestCourse: nearest.course,
    daysUntil: countdown
  }
}

/**
 * 获取历史考试（已结束的考试）
 * @param {Date} now
 * @returns {Array}
 */
export function getHistoryExams(now) {
  const exams = getExams()
  return exams
    .filter(e => {
      // 考试结束时间 <= 当前时间 才算历史考试
      const examEnd = parseDateTime(`${e.date}T${e.endTime}:00`)
      return examEnd <= now
    })
    .sort((a, b) => {
      // 按结束时间倒序排列，最近结束的在前面
      const dateA = parseDateTime(`${a.date}T${a.endTime}:00`)
      const dateB = parseDateTime(`${b.date}T${b.endTime}:00`)
      return dateB - dateA
    })
}

/**
 * 待办逻辑模块
 * 提供待办筛选、分类、倒计时等功能
 */

import { getTasks, updateTaskStatus } from './storage'
import { parseDateTime, getNow, isToday } from './time'

/**
 * 获取已逾期待办（截止时间早于当前时间且未完成）
 * @param {Date} now
 * @returns {Array}
 */
export function getOverdueTasks(now) {
  const tasks = getTasks()
  return tasks.filter(t => {
    if (t.finished) return false
    const deadline = parseDateTime(t.deadline)
    return deadline < now
  }).sort((a, b) => parseDateTime(a.deadline) - parseDateTime(b.deadline))
}

/**
 * 获取今日待办（今天截止且未过期、未完成）
 * @param {Date} now
 * @returns {Array}
 */
export function getTodayTasks(now) {
  const tasks = getTasks()
  return tasks.filter(t => {
    if (t.finished) return false
    const deadline = parseDateTime(t.deadline)
    // 今天截止且尚未过期
    return isToday(deadline, now) && deadline >= now
  }).sort((a, b) => parseDateTime(a.deadline) - parseDateTime(b.deadline))
}

/**
 * 获取本周结束日期（周日 23:59:59.999）
 * @param {Date} now
 * @returns {Date}
 */
function getWeekEnd(now) {
  const weekEnd = new Date(now)
  // 将 JavaScript 的周日=0 转换为业务中的周日=7
  const day = weekEnd.getDay() === 0 ? 7 : weekEnd.getDay()
  weekEnd.setDate(weekEnd.getDate() + (7 - day))
  weekEnd.setHours(23, 59, 59, 999)
  return weekEnd
}

/**
 * 获取本周待办（本周内、非今天、未过期、未完成）
 * @param {Date} now
 * @returns {Array}
 */
export function getWeekTasks(now) {
  const tasks = getTasks()
  const weekEnd = getWeekEnd(now)

  return tasks.filter(t => {
    if (t.finished) return false
    const deadline = parseDateTime(t.deadline)
    return deadline > now && deadline <= weekEnd && !isToday(deadline, now)
  }).sort((a, b) => parseDateTime(a.deadline) - parseDateTime(b.deadline))
}

/**
 * 获取未来待办（本周之后、未完成）
 * @param {Date} now
 * @returns {Array}
 */
export function getFutureTasks(now) {
  const tasks = getTasks()
  const weekEnd = getWeekEnd(now)

  return tasks.filter(t => {
    if (t.finished) return false
    const deadline = parseDateTime(t.deadline)
    return deadline > weekEnd
  }).sort((a, b) => parseDateTime(a.deadline) - parseDateTime(b.deadline))
}

/**
 * 获取已完成待办
 * @returns {Array}
 */
export function getFinishedTasks() {
  const tasks = getTasks()
  return tasks.filter(t => t.finished)
}

/**
 * 获取待办剩余时间
 * @param {object} task
 * @param {Date} now
 * @returns {object} { value, unit, isUrgent, isCritical }
 */
export function getTaskCountdown(task, now) {
  const deadline = parseDateTime(task.deadline)
  const remaining = deadline - now

  if (remaining <= 0) {
    return { value: 0, unit: '已截止', isUrgent: false, isCritical: true }
  }

  const minutes = Math.floor(remaining / (1000 * 60))
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)

  // 判断紧急程度
  const isCritical = hours < 1
  const isUrgent = hours < 6

  if (days > 0) {
    return { value: days, unit: '天', isUrgent, isCritical }
  }
  if (hours > 0) {
    return { value: hours, unit: '小时', isUrgent, isCritical }
  }
  return { value: minutes, unit: '分钟', isUrgent, isCritical }
}

/**
 * 格式化待办倒计时文字
 * @param {object} task
 * @param {Date} now
 * @returns {string}
 */
export function formatTaskCountdown(task, now) {
  const countdown = getTaskCountdown(task, now)
  if (countdown.unit === '已截止') return '已截止'
  return `还有 ${countdown.value} ${countdown.unit}`
}

/**
 * 获取待办摘要
 * @param {Date} now
 * @returns {object} { todayCount, totalCount, urgentCount }
 */
export function getTaskSummary(now) {
  const todayTasks = getTodayTasks(now)
  const allTasks = getTasks().filter(t => !t.finished)
  const urgentCount = allTasks.filter(t => {
    const countdown = getTaskCountdown(t, now)
    return countdown.isUrgent
  }).length

  return {
    todayCount: todayTasks.length,
    totalCount: allTasks.length,
    urgentCount
  }
}

/**
 * 切换任务完成状态
 * @param {string} taskId
 * @param {boolean} newStatus
 * @returns {Promise<boolean>}
 */
export function toggleTaskStatus(taskId, newStatus) {
  return updateTaskStatus(taskId, newStatus)
}

/**
 * 获取待办类型文字
 * @param {string} type
 * @returns {string}
 */
export function getTaskTypeText(type) {
  const typeMap = {
    experiment: '实验',
    homework: '作业',
    report: '报告',
    other: '其他'
  }
  return typeMap[type] || '其他'
}

/**
 * 本地存储模块
 * 使用 @system.storage 实现离线数据持久化
 * 内存缓存 + system.storage 持久化
 */

import storage from '@system.storage'
import { courses, exams, tasks } from './data'

const STORAGE_KEYS = {
  COURSES: 'campus_courses',
  EXAMS: 'campus_exams',
  TASKS: 'campus_tasks',
  SEMESTER_START: 'campus_semester_start',
  DEBUG_USE_MOCK_DATA: 'debug_use_mock_data'
}

// 内存缓存
let courseCache = []
let examCache = []
let taskCache = []
let semesterWeek1StartCache = null // 学期第一周周一日期字符串 YYYY-MM-DD
let useMockDataCache = true // 默认启用Mock数据
let storageReady = false
let initPromise = null

/**
 * 同步Mock数据设置状态
 * 从Storage读取最新状态并更新缓存
 * @returns {Promise<boolean>}
 */
export function syncMockDataSetting() {
  return new Promise((resolve) => {
    storage.get({
      key: STORAGE_KEYS.DEBUG_USE_MOCK_DATA,
      success: function (data) {
        if (data === 'true') {
          useMockDataCache = true
        } else if (data === 'false') {
          useMockDataCache = false
        }
        resolve(useMockDataCache)
      },
      fail: function () {
        resolve(useMockDataCache)
      }
    })
  })
}

/**
 * 初始化存储（单例）
 * 从 system.storage 读取数据，如果不存在则使用 Mock数据
 * @returns {Promise}
 */
export function initStorage() {
  if (storageReady) {
    return Promise.resolve()
  }

  if (initPromise) {
    return initPromise
  }

  initPromise = new Promise((resolve) => {
    let loaded = 0
    const total = 5

    const checkComplete = () => {
      loaded++
      if (loaded >= total) {
        storageReady = true
        resolve()
      }
    }

    // 读取Mock数据设置
    storage.get({
      key: STORAGE_KEYS.DEBUG_USE_MOCK_DATA,
      success: function (data) {
        if (data === 'true') {
          useMockDataCache = true
        } else if (data === 'false') {
          useMockDataCache = false
        }
        checkComplete()
      },
      fail: function () {
        checkComplete()
      }
    })

    // 读取课程
    storage.get({
      key: STORAGE_KEYS.COURSES,
      success: function (data) {
        try {
          courseCache = data ? JSON.parse(data) : []
        } catch (e) {
          courseCache = []
        }
        checkComplete()
      },
      fail: function () {
        courseCache = []
        checkComplete()
      }
    })

    // 读取考试
    storage.get({
      key: STORAGE_KEYS.EXAMS,
      success: function (data) {
        try {
          examCache = data ? JSON.parse(data) : []
        } catch (e) {
          examCache = []
        }
        checkComplete()
      },
      fail: function () {
        examCache = []
        checkComplete()
      }
    })

    // 读取任务
    storage.get({
      key: STORAGE_KEYS.TASKS,
      success: function (data) {
        try {
          taskCache = data ? JSON.parse(data) : []
        } catch (e) {
          taskCache = []
        }
        checkComplete()
      },
      fail: function () {
        taskCache = []
        checkComplete()
      }
    })

    // 读取学期第一周设置
    storage.get({
      key: STORAGE_KEYS.SEMESTER_START,
      success: function (data) {
        semesterWeek1StartCache = data || null
        checkComplete()
      },
      fail: function () {
        semesterWeek1StartCache = null
        checkComplete()
      }
    })
  })

  return initPromise
}

/**
 * 确保 Storage 已初始化完成
 * @returns {Promise}
 */
export function ensureStorageReady() {
  if (storageReady) {
    return Promise.resolve()
  }
  return initStorage()
}

/**
 * 获取课程数据
 * @returns {Array}
 */
export function getCourses() {
  if (useMockDataCache) {
    const userCourseIds = courseCache.map(c => c.id)
    const mockCourses = courses.filter(c => !userCourseIds.includes(c.id))
    return [...mockCourses, ...courseCache]
  }
  return courseCache
}

/**
 * 获取考试数据
 * @returns {Array}
 */
export function getExams() {
  if (useMockDataCache) {
    const userExamIds = examCache.map(e => e.id)
    const mockExams = exams.filter(e => !userExamIds.includes(e.id))
    return [...mockExams, ...examCache]
  }
  return examCache
}

/**
 * 获取待办数据
 * @returns {Array}
 */
export function getTasks() {
  if (useMockDataCache) {
    const userTaskIds = taskCache.map(t => t.id)
    const mockTasks = tasks.filter(t => !userTaskIds.includes(t.id))
    return [...mockTasks, ...taskCache]
  }
  return taskCache
}

/**
 * 从Storage读取是否使用默认Mock数据
 * 与 syncMockDataSetting 复用同一套逻辑
 * @returns {Promise<boolean>}
 */
export function getUseMockDataFromStorage() {
  return syncMockDataSetting()
}

/**
 * 设置是否使用默认Mock数据
 * @param {boolean} useMock
 * @returns {Promise}
 */
export function setUseMockData(useMock) {
  return new Promise((resolve, reject) => {
    const oldValue = useMockDataCache

    storage.set({
      key: STORAGE_KEYS.DEBUG_USE_MOCK_DATA,
      value: String(useMock),
      success: function () {
        useMockDataCache = useMock
        resolve()
      },
      fail: function (data, code) {
        useMockDataCache = oldValue
        reject(new Error('Failed to save setting'))
      }
    })
  })
}

/**
 * 更新任务状态并持久化（不可变更新）
 * @param {string} taskId
 * @param {boolean} finished
 * @returns {Promise<boolean>}
 */
export function updateTaskStatus(taskId, finished) {
  return new Promise((resolve, reject) => {
    const index = taskCache.findIndex(t => t.id === taskId)
    if (index === -1) {
      reject(new Error('Task not found'))
      return
    }

    const oldTaskCache = taskCache

    taskCache = taskCache.map(task => {
      if (task.id !== taskId) {
        return task
      }
      return { ...task, finished: finished }
    })

    storage.set({
      key: STORAGE_KEYS.TASKS,
      value: JSON.stringify(taskCache),
      success: function () {
        resolve(true)
      },
      fail: function (data, code) {
        taskCache = oldTaskCache
        reject(new Error('Failed to save task status'))
      }
    })
  })
}

/**
 * 从 Storage 重新读取任务数据
 * @returns {Promise<Array>}
 */
export function refreshTasksFromStorage() {
  return new Promise((resolve, reject) => {
    storage.get({
      key: STORAGE_KEYS.TASKS,
      success: function (data) {
        try {
          const parsed = data ? JSON.parse(data) : []
          taskCache = parsed.map(task => ({ ...task }))
          resolve(taskCache)
        } catch (e) {
          resolve(taskCache)
        }
      },
      fail: function () {
        resolve(taskCache)
      }
    })
  })
}

